@page "/settings"
@using sv_50cd28fd10214877be0f47f070c0c484.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <h2>Settings</h2>
        <ul>
            <li class="@(ActiveSection == "Profile" ? "active" : "")" @onclick='() => SetSection("Profile")'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(ActiveSection == "Notifications" ? "active" : "")" @onclick='() => SetSection("Notifications")'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(ActiveSection == "Security" ? "active" : "")" @onclick='() => SetSection("Security")'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(ActiveSection == "Appearance" ? "active" : "")" @onclick='() => SetSection("Appearance")'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (IsLoading)
        {
            <div class="loading">Loading settings...</div>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "Profile":
                    @RenderProfileSection()
                    break;
                case "Notifications":
                    @RenderNotificationsSection()
                    break;
                case "Security":
                    @RenderSecuritySection()
                    break;
                case "Appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }

        @if (!string.IsNullOrEmpty(ToastMessage))
        {
            <div class="toast @ToastType">
                @ToastMessage
                <button class="toast-close" @onclick="DismissToast">✕</button>
            </div>
        }
    </main>
</div>

@code {
    private string ActiveSection { get; set; } = "Profile";
    private bool IsLoading { get; set; } = true;
    private string? ToastMessage { get; set; }
    private string ToastType { get; set; } = "success";

    // Profile state
    private string ProfileDisplayName { get; set; } = "";
    private string ProfileEmail { get; set; } = "";
    private string ProfileAvatarUrl { get; set; } = "";
    private string ProfileBio { get; set; } = "";
    private UserProfile? _savedProfile;

    // Notifications state
    private bool NotifEmail { get; set; }
    private bool NotifPush { get; set; }
    private bool NotifWeeklyDigest { get; set; }
    private List<ChannelItem> Channels { get; set; } = new();

    // Security state
    private SecuritySettings? SecurityData { get; set; }
    private bool PasswordPanelExpanded { get; set; }
    private string CurrentPassword { get; set; } = "";
    private string NewPassword { get; set; } = "";
    private string ConfirmPassword { get; set; } = "";
    private bool TwoFactorEnabled { get; set; }
    private string? RevokeConfirmSessionId { get; set; }

    // Appearance state
    private string SelectedTheme { get; set; } = "Light";
    private string SelectedFontSize { get; set; } = "Medium";
    private string SelectedLanguage { get; set; } = "English";
    private bool CompactMode { get; set; }

    private readonly string[] AvailableLanguages = { "English", "Spanish", "French", "German", "Japanese", "Chinese" };

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
        IsLoading = false;
    }

    private async Task LoadAllSettings()
    {
        var profile = await SettingsService.GetProfileAsync();
        _savedProfile = profile;
        ApplyProfile(profile);

        var notifs = await SettingsService.GetNotificationPrefsAsync();
        NotifEmail = notifs.EmailNotifications;
        NotifPush = notifs.PushNotifications;
        NotifWeeklyDigest = notifs.WeeklyDigest;
        Channels = notifs.MutedChannels.Select(c => new ChannelItem(c, true)).ToList();

        SecurityData = await SettingsService.GetSecuritySettingsAsync();
        TwoFactorEnabled = SecurityData.TwoFactorEnabled;

        var appearance = await SettingsService.GetAppearanceAsync();
        SelectedTheme = appearance.Theme;
        SelectedFontSize = appearance.FontSize;
        SelectedLanguage = appearance.Language;
        CompactMode = appearance.CompactMode;
    }

    private void ApplyProfile(UserProfile profile)
    {
        ProfileDisplayName = profile.DisplayName;
        ProfileEmail = profile.Email;
        ProfileAvatarUrl = profile.AvatarUrl;
        ProfileBio = profile.Bio;
    }

    private void SetSection(string section) => ActiveSection = section;

    // Toast helpers
    private void ShowToast(string message, string type = "success")
    {
        ToastMessage = message;
        ToastType = type;
    }

    private void DismissToast() => ToastMessage = null;

    // Profile methods
    private async Task SaveProfile()
    {
        var profile = new UserProfile(ProfileDisplayName, ProfileEmail, ProfileAvatarUrl, ProfileBio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        ShowToast("Profile saved successfully!");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null)
        {
            ApplyProfile(_savedProfile);
            ShowToast("Changes discarded.", "info");
        }
    }

    // Notifications methods
    private async Task SaveNotificationPrefs()
    {
        var mutedChannels = Channels.Where(c => c.IsMuted).Select(c => c.Name).ToList();
        var prefs = new NotificationPrefs(NotifEmail, NotifPush, NotifWeeklyDigest, mutedChannels);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        ShowToast("Notification preferences saved!");
    }

    // Security methods
    private async Task ChangePassword()
    {
        if (string.IsNullOrWhiteSpace(CurrentPassword) || string.IsNullOrWhiteSpace(NewPassword))
        {
            ShowToast("Please fill in all password fields.", "error");
            return;
        }
        if (NewPassword != ConfirmPassword)
        {
            ShowToast("New password and confirmation do not match.", "error");
            return;
        }
        await SettingsService.ChangePasswordAsync(CurrentPassword, NewPassword);
        CurrentPassword = "";
        NewPassword = "";
        ConfirmPassword = "";
        PasswordPanelExpanded = false;
        SecurityData = await SettingsService.GetSecuritySettingsAsync();
        ShowToast("Password updated successfully!");
    }

    private void RequestRevokeSession(string sessionId) => RevokeConfirmSessionId = sessionId;

    private void CancelRevoke() => RevokeConfirmSessionId = null;

    private async Task ConfirmRevokeSession()
    {
        if (RevokeConfirmSessionId is not null)
        {
            await SettingsService.RevokeSessionAsync(RevokeConfirmSessionId);
            SecurityData = await SettingsService.GetSecuritySettingsAsync();
            RevokeConfirmSessionId = null;
            ShowToast("Session revoked.");
        }
    }

    // Appearance methods
    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(SelectedTheme, SelectedFontSize, SelectedLanguage, CompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        ShowToast("Appearance settings saved!");
    }

    // Render methods
    private RenderFragment RenderProfileSection() => __builder =>
    {
        <section class="settings-section">
            <h3>Profile</h3>

            <div class="avatar-area">
                <div class="avatar-preview">
                    <img src="@ProfileAvatarUrl" alt="Avatar" />
                </div>
                <div class="avatar-url">
                    <label>Avatar URL</label>
                    <input type="text" @bind="ProfileAvatarUrl" placeholder="https://..." />
                </div>
            </div>

            <div class="form-group">
                <label>Display Name</label>
                <input type="text" @bind="ProfileDisplayName" />
            </div>

            <div class="form-group">
                <label>Email</label>
                <input type="email" @bind="ProfileEmail" />
            </div>

            <div class="form-group">
                <label>Bio</label>
                <textarea rows="4" @bind="ProfileBio"></textarea>
            </div>

            <div class="button-group">
                <button class="btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </section>
    };

    private RenderFragment RenderNotificationsSection() => __builder =>
    {
        <section class="settings-section">
            <h3>Notifications</h3>

            <div class="toggle-group">
                <label class="toggle-row">
                    <span>Email Notifications</span>
                    <input type="checkbox" @bind="NotifEmail" class="toggle-switch" />
                </label>
                <label class="toggle-row">
                    <span>Push Notifications</span>
                    <input type="checkbox" @bind="NotifPush" class="toggle-switch" />
                </label>
                <label class="toggle-row">
                    <span>Weekly Digest</span>
                    <input type="checkbox" @bind="NotifWeeklyDigest" class="toggle-switch" />
                </label>
            </div>

            <h4>Muted Channels</h4>
            <div class="channel-list">
                @foreach (var channel in Channels)
                {
                    <label class="channel-item">
                        <input type="checkbox" @bind="channel.IsMuted" />
                        <span>#@channel.Name</span>
                    </label>
                }
            </div>

            <div class="button-group">
                <button class="btn-primary" @onclick="SaveNotificationPrefs">Save Preferences</button>
            </div>
        </section>
    };

    private RenderFragment RenderSecuritySection() => __builder =>
    {
        <section class="settings-section">
            <h3>Security</h3>

            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => PasswordPanelExpanded = !PasswordPanelExpanded">
                    <span>Change Password</span>
                    <span class="expand-icon">@(PasswordPanelExpanded ? "▼" : "▶")</span>
                </button>
                @if (PasswordPanelExpanded)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label>Current Password</label>
                            <input type="password" @bind="CurrentPassword" />
                        </div>
                        <div class="form-group">
                            <label>New Password</label>
                            <input type="password" @bind="NewPassword" />
                        </div>
                        <div class="form-group">
                            <label>Confirm Password</label>
                            <input type="password" @bind="ConfirmPassword" />
                        </div>
                        <button class="btn-primary" @onclick="ChangePassword">Update Password</button>
                    </div>
                }
            </div>

            @if (SecurityData?.LastPasswordChange is not null)
            {
                <p class="hint-text">Last password change: @SecurityData.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }

            <div class="toggle-group" style="margin-top: 1.5rem;">
                <label class="toggle-row">
                    <span>
                        Two-Factor Authentication
                        <span class="status-badge @(TwoFactorEnabled ? "enabled" : "disabled")">
                            @(TwoFactorEnabled ? "Enabled" : "Disabled")
                        </span>
                    </span>
                    <input type="checkbox" @bind="TwoFactorEnabled" class="toggle-switch" />
                </label>
            </div>

            <h4>Active Sessions</h4>
            @if (SecurityData?.Sessions is not null)
            {
                <div class="sessions-table-wrapper">
                    <table class="sessions-table">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th></th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in SecurityData.Sessions)
                            {
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@FormatLastActive(session.LastActive)</td>
                                    <td>
                                        @if (session.Id != SecurityData.Sessions.First().Id)
                                        {
                                            <button class="btn-danger-sm" @onclick="() => RequestRevokeSession(session.Id)">Revoke</button>
                                        }
                                        else
                                        {
                                            <span class="current-badge">Current</span>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>
                </div>
            }

            @if (RevokeConfirmSessionId is not null)
            {
                <div class="modal-overlay">
                    <div class="modal-dialog">
                        <h4>Revoke Session</h4>
                        <p>Are you sure you want to revoke this session? The device will be logged out immediately.</p>
                        <div class="button-group">
                            <button class="btn-danger" @onclick="ConfirmRevokeSession">Revoke</button>
                            <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
                        </div>
                    </div>
                </div>
            }
        </section>
    };

    private RenderFragment RenderAppearanceSection() => __builder =>
    {
        <section class="settings-section">
            <h3>Appearance</h3>

            <div class="form-group">
                <label>Theme</label>
                <div class="radio-group">
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <label class="radio-item">
                            <input type="radio" name="theme" value="@theme" checked="@(SelectedTheme == theme)" @onchange="() => SelectedTheme = theme" />
                            @theme
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label>Font Size</label>
                <div class="radio-group">
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <label class="radio-item">
                            <input type="radio" name="fontSize" value="@size" checked="@(SelectedFontSize == size)" @onchange="() => SelectedFontSize = size" />
                            @size
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label>Language</label>
                <select @bind="SelectedLanguage">
                    @foreach (var lang in AvailableLanguages)
                    {
                        <option value="@lang">@lang</option>
                    }
                </select>
            </div>

            <div class="toggle-group">
                <label class="toggle-row">
                    <span>Compact Mode</span>
                    <input type="checkbox" @bind="CompactMode" class="toggle-switch" />
                </label>
            </div>

            <h4>Preview</h4>
            <div class="appearance-preview @GetPreviewClasses()">
                <div class="preview-header">Sample Header</div>
                <p class="preview-text">This is how your content will look with the selected appearance settings.</p>
                <button class="preview-button">Sample Button</button>
            </div>

            <div class="button-group">
                <button class="btn-primary" @onclick="SaveAppearance">Save</button>
            </div>
        </section>
    };

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add($"preview-theme-{SelectedTheme.ToLower()}");
        classes.Add($"preview-font-{SelectedFontSize.ToLower()}");
        if (CompactMode) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }

    public class ChannelItem
    {
        public string Name { get; set; }
        public bool IsMuted { get; set; }
        public ChannelItem(string name, bool isMuted) { Name = name; IsMuted = isMuted; }
    }
}

