}

/* Toast */
.toast {
    position: fixed;
    bottom: 1.5rem;
    right: 1.5rem;
    padding: 0.85rem 1.25rem;
    border-radius: 8px;
    font-size: 0.9rem;
    display: flex;
    align-items: center;
    gap: 0.75rem;
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.15);
    z-index: 1100;
    animation: slideIn 0.25s ease;
}

.toast.success {
    background: #e6f4ea;
    color: #1e8e3e;
    border: 1px solid #a8dab5;
}

.toast.error {
    background: #fce8e6;
    color: #d93025;
    border: 1px solid #f5c6cb;
}

.toast.info {
    background: #e8f0fe;
    color: #1a73e8;
    border: 1px solid #a8c7fa;
}

.toast-close {
    background: none;
    border: none;
    cursor: pointer;
    font-size: 1rem;
    opacity: 0.6;
    color: inherit;
}

.toast-close:hover {
    opacity: 1;
}

@@keyframes slideIn {
    from {
        transform: translateY(1rem);
        opacity: 0;
    }
    to {
        transform: translateY(0);
        opacity: 1;
    }
}

