    private void DismissToast() => ToastMessage = null;

    // Profile methods
    private async Task SaveProfile()
    {
        var profile = new UserProfile(ProfileDisplayName, ProfileEmail, ProfileAvatarUrl, ProfileBio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        ShowToast("Profile saved successfully!");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null)
        {
            ApplyProfile(_savedProfile);
            ShowToast("Changes discarded.", "info");
        }
    }

    // Notifications methods
    private async Task SaveNotificationPrefs()
    {
        var mutedChannels = Channels.Where(c => c.IsMuted).Select(c => c.Name).ToList();
        var prefs = new NotificationPrefs(NotifEmail, NotifPush, NotifWeeklyDigest, mutedChannels);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        ShowToast("Notification preferences saved!");
    }

    // Security methods
    private async Task ChangePassword()
    {
        if (string.IsNullOrWhiteSpace(CurrentPassword) || string.IsNullOrWhiteSpace(NewPassword))
        {
            ShowToast("Please fill in all password fields.", "error");
            return;
        }
        if (NewPassword != ConfirmPassword)
        {
            ShowToast("New password and confirmation do not match.", "error");
            return;
        }
        await SettingsService.ChangePasswordAsync(CurrentPassword, NewPassword);
        CurrentPassword = "";
        NewPassword = "";
        ConfirmPassword = "";
        PasswordPanelExpanded = false;
        SecurityData = await SettingsService.GetSecuritySettingsAsync();
        ShowToast("Password updated successfully!");
    }

    private void RequestRevokeSession(string sessionId) => RevokeConfirmSessionId = sessionId;

    private void CancelRevoke() => RevokeConfirmSessionId = null;

    private async Task ConfirmRevokeSession()
    {
        if (RevokeConfirmSessionId is not null)
