                                        {
                                            <button class="btn-danger-sm" @onclick="() => RequestRevokeSession(session.Id)">Revoke</button>
                                        }
                                        else
                                        {
                                            <span class="current-badge">Current</span>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>
                </div>
            }

            @if (RevokeConfirmSessionId is not null)
            {
                <div class="modal-overlay">
                    <div class="modal-dialog">
                        <h4>Revoke Session</h4>
                        <p>Are you sure you want to revoke this session? The device will be logged out immediately.</p>
                        <div class="button-group">
                            <button class="btn-danger" @onclick="ConfirmRevokeSession">Revoke</button>
                            <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
