.status-badge {
    display: inline-block;
    padding: 0.2rem 0.5rem;
    border-radius: 4px;
    font-size: 0.75rem;
    font-weight: 600;
    margin-left: 0.5rem;
}

.status-badge.enabled {
    background: #e6f4ea;
    color: #1e8e3e;
}

.status-badge.disabled {
    background: #fce8e6;
    color: #d93025;
}

.current-badge {
    font-size: 0.8rem;
    color: #1a73e8;
    font-weight: 500;
}

.hint-text {
    font-size: 0.85rem;
    color: #666;
    margin: 0.5rem 0;
}

/* Sessions table */
.sessions-table-wrapper {
    overflow-x: auto;
}

.sessions-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.9rem;
}

.sessions-table th {
    text-align: left;
    padding: 0.6rem 0.75rem;
    border-bottom: 2px solid #e0e0e0;
    color: #555;
    font-weight: 600;
    font-size: 0.85rem;
}

.sessions-table td {
    padding: 0.6rem 0.75rem;
    border-bottom: 1px solid #f0f0f0;
    color: #333;
}

/* Radio group */
.radio-group {
    display: flex;
    gap: 1.25rem;
    margin-top: 0.25rem;
}

.radio-item {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
    font-size: 0.95rem;
    color: #444;
}

/* Appearance preview */
.appearance-preview {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 1.5rem;
    margin-bottom: 1rem;
    max-width: 450px;
    transition: all 0.2s ease;
}

.appearance-preview.preview-theme-light {
    background: #ffffff;
    color: #333;
}

.appearance-preview.preview-theme-dark {
    background: #1e1e2e;
    color: #e0e0e0;
    border-color: #444;
}

.appearance-preview.preview-theme-system {
    background: linear-gradient(135deg, #ffffff 50%, #1e1e2e 50%);
    color: #333;
}

.appearance-preview.preview-font-small {
    font-size: 0.8rem;
}

.appearance-preview.preview-font-medium {
    font-size: 1rem;
}

.appearance-preview.preview-font-large {
    font-size: 1.2rem;
}

.appearance-preview.preview-compact {
    padding: 0.75rem;
    line-height: 1.3;
}

.preview-header {
    font-weight: 600;
    font-size: 1.2em;
    margin-bottom: 0.5rem;
}

.preview-text {
    margin-bottom: 0.75rem;
    opacity: 0.85;
}

.preview-button {
    padding: 0.4rem 0.85rem;
    border-radius: 4px;
    border: none;
    background: #1a73e8;
    color: white;
    cursor: pointer;
    font-size: 0.85em;
}

/* Modal */
.modal-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.4);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.modal-dialog {
    background: white;
    border-radius: 10px;
    padding: 1.5rem 2rem;
    max-width: 400px;
    width: 90%;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.2);
}

.modal-dialog h4 {
    margin: 0 0 0.75rem;
}

.modal-dialog p {
    color: #555;
    font-size: 0.9rem;
    margin-bottom: 1rem;
}

/* Toast */
.toast {
    position: fixed;
    bottom: 1.5rem;
    right: 1.5rem;
    padding: 0.85rem 1.25rem;
    border-radius: 8px;
    font-size: 0.9rem;
    display: flex;
    align-items: center;
    gap: 0.75rem;
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.15);
    z-index: 1100;
    animation: slideIn 0.25s ease;
}

.toast.success {
    background: #e6f4ea;
    color: #1e8e3e;
    border: 1px solid #a8dab5;
}

.toast.error {
    background: #fce8e6;
    color: #d93025;
    border: 1px solid #f5c6cb;
}

.toast.info {
    background: #e8f0fe;
    color: #1a73e8;
    border: 1px solid #a8c7fa;
}

.toast-close {
    background: none;
    border: none;
    cursor: pointer;
    font-size: 1rem;
    opacity: 0.6;
    color: inherit;
}

.toast-close:hover {
    opacity: 1;
}

@@keyframes slideIn {
    from {
        transform: translateY(1rem);
        opacity: 0;
    }
    to {
        transform: translateY(0);
        opacity: 1;
    }
}

